package glitch

import data.glitch_lib

weak_algorithm_values := {"des", "3des", "rc4", "rc2", "idea", "blowfish", "seed", "xor", "rot13", "ecb", "null", "export"}
weak_protocol_values := {"sslv2", "sslv3", "tls1.0", "tls1.1", "tlsv1.0", "tlsv1.1"}
weak_cipher_values := {"rc4", "des", "3des", "md5", "sha1", "null", "export"}
weak_mode_values := {"ecb"}
legacy_flag_fields := {"allow_weak", "enable_legacy", "compatibility", "disable_strong", "fallback"}

algorithm_fields := {"algorithm", "cipher", "encryption_type", "encryption_algorithm"}
protocol_fields := {"protocol", "ssl_protocol", "tls_version", "min_protocol_version", "security_policy"}
cipher_fields := {"cipher_suites", "allowed_ciphers", "ssl_policy", "security_policy"}
keysize_fields := {"key_size", "key_length", "keysize", "keylength", "bits", "rsa_bits", "dh_group", "dh_size", "curve", "key_spec"}
mode_fields := {"mode", "block_mode", "padding"}

weak_sym_sizes := {40, 56, 64, 80, 112, 128}
weak_asym_sizes := {1024, 1536}
weak_keysize_string_patterns := {"40", "56", "64", "80", "112", "128", "1024", "1536", "160", "192"}

weak_description := "Inadequate encryption strength - Weak cryptographic configuration detected. (CWE-326)"

all_keyvalues(node) = kvs {
    attrs := glitch_lib.all_attributes(node)
    vars := glitch_lib.all_variables(node)
    kvs := attrs | vars
}

field_match(name, fields) {
    some f
    f := fields[_]
    glitch_lib.contains(name, f)
}

value_contains(value, patterns) {
    glitch_lib.traverse(value, patterns)
}

weak_key_size_number(name, n) {
    glitch_lib.contains(name, "curve")
    n < 224
}
weak_key_size_number(name, n) {
    (glitch_lib.contains(name, "rsa") or glitch_lib.contains(name, "dh"))
    n <= 1536
}
weak_key_size_number(name, n) {
    n == weak_sym_sizes[_]
}
weak_key_size_number(name, n) {
    n == weak_asym_sizes[_]
}

weak_key_size_string(name, s) {
    regex.match("^[0-9]+$", s)
    n := to_number(s)
    weak_key_size_number(name, n)
}
weak_key_size_string(name, s) {
    some w
    w := weak_keysize_string_patterns[_]
    glitch_lib.contains(s, w)
}

weak_key_size_value(val, name) {
    walk(val, [_, v])
    v.ir_type == "Integer"
    weak_key_size_number(name, v.value)
}
weak_key_size_value(val, name) {
    walk(val, [_, v])
    v.ir_type == "Float"
    weak_key_size_number(name, v.value)
}
weak_key_size_value(val, name) {
    walk(val, [_, v])
    v.ir_type == "String"
    weak_key_size_string(name, v.value)
}

is_true(val) {
    val.ir_type == "Boolean"
    val.value == true
}
is_true(val) {
    val.ir_type == "String"
    regex.match("(?i)^(true|yes|1|on|enabled)$", val.value)
}
is_true(val) {
    val.ir_type == "Integer"
    val.value == 1
}

is_constant_value(val) {
    val.ir_type == "String"
}
is_constant_value(val) {
    val.ir_type == "Integer"
}
is_constant_value(val) {
    val.ir_type == "Float"
}

iv_or_salt_field(name) {
    regex.match("(?i)^iv$", name)
}
iv_or_salt_field(name) {
    regex.match("(?i)^salt$", name)
}
iv_or_salt_field(name) {
    glitch_lib.contains(name, "iv_")
}
iv_or_salt_field(name) {
    glitch_lib.contains(name, "_iv")
}
iv_or_salt_field(name) {
    glitch_lib.contains(name, "salt_")
}
iv_or_salt_field(name) {
    glitch_lib.contains(name, "_salt")
}

weak_iv_or_salt(val) {
    is_constant_value(val)
    glitch_lib.traverse_var(val)
}

weak_crypto_kv(kv) {
    field_match(kv.name, algorithm_fields)
    value_contains(kv.value, weak_algorithm_values)
}
weak_crypto_kv(kv) {
    field_match(kv.name, protocol_fields)
    value_contains(kv.value, weak_protocol_values)
}
weak_crypto_kv(kv) {
    field_match(kv.name, cipher_fields)
    value_contains(kv.value, weak_cipher_values)
}
weak_crypto_kv(kv) {
    field_match(kv.name, keysize_fields)
    weak_key_size_value(kv.value, kv.name)
}
weak_crypto_kv(kv) {
    field_match(kv.name, mode_fields)
    value_contains(kv.value, weak_mode_values)
}
weak_crypto_kv(kv) {
    iv_or_salt_field(kv.name)
    weak_iv_or_salt(kv.value)
}
weak_crypto_kv(kv) {
    field_match(kv.name, legacy_flag_fields)
    is_true(kv.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    kvs := all_keyvalues(parent)
    kv := kvs[_]
    weak_crypto_kv(kv)

    result := {
        "type": "sec_weak_crypt",
        "element": kv,
        "path": parent.path,
        "description": weak_description
    }
}

