package glitch

import data.glitch_lib

algorithm_fields := {"algorithm", "cipher", "encryption", "encryption_type", "encryption_algorithm", "encrypt", "hash", "digest", "crypt"}
protocol_fields := {"protocol", "ssl_protocol", "tls_version", "min_protocol_version", "security_policy"}
cipher_fields := {"cipher_suites", "allowed_ciphers", "ssl_policy", "security_policy", "ciphers"}
keysize_fields := {"key_size", "key_length", "keysize", "keylength", "bits", "rsa_bits", "dh_group_size", "dh_size", "curve", "key_spec"}
mode_fields := {"mode", "block_mode", "padding", "cipher_mode"}
legacy_flag_fields := {"allow_weak", "enable_legacy", "compatibility", "disable_strong", "fallback"}

weak_sym_sizes := {40, 56, 64, 80, 112, 128}
weak_asym_sizes := {1024, 1536}
weak_keysize_tokens := {"40", "56", "64", "80", "112", "128", "1024", "1536"}
weak_protocol_patterns := {"sslv2", "sslv3", "tls1\\.0", "tls1\\.1", "tlsv1\\.0", "tlsv1\\.1"}

weak_description := "Inadequate encryption strength - Weak cryptographic configuration detected. (CWE-326)"

field_match(name, fields) {
    f := fields[_]
    glitch_lib.contains(name, f)
}

kv_pair(node, name, value, element) {
    attr := glitch_lib.all_attributes(node)[_]
    name := attr.name
    value := attr.value
    element := attr
}

kv_pair(node, name, value, element) {
    var := glitch_lib.all_variables(node)[_]
    name := var.name
    value := var.value
    element := var
}

kv_pair(node, name, value, element) {
    walk(node, [_, h])
    h.ir_type == "Hash"
    pair := h.value[_]
    key := pair.key
    key.ir_type == "String"
    name := key.value
    value := pair.value
    element := pair.value
}

kv_pair(node, name, value, element) {
    walk(node, [_, h])
    h.ir_type == "Hash"
    pair := h.value[_]
    key := pair.key
    key.ir_type == "VariableReference"
    name := key.value
    value := pair.value
    element := pair.value
}

weak_algo_string(s) {
    regex.match("(?i).*([^a-z0-9]|^)(des|3des|rc4|rc2|idea|blowfish|seed|xor|rot13|null|export|md5)([^a-z0-9]|$).*", s)
}

weak_algo_string(s) {
    regex.match("(?i).*sha[-_]?1([^0-9]|$).*", s)
}

weak_protocol_string(s) {
    p := weak_protocol_patterns[_]
    regex.match(sprintf("(?i).*%s.*", [p]), s)
}

weak_cipher_string(s) {
    weak_algo_string(s)
}

weak_cipher_string(s) {
    regex.match("(?i).*_SHA([^0-9]|$).*", s)
}

weak_mode_string(s) {
    regex.match("(?i).*\\becb\\b.*", s)
}

value_has_weak_algo(val) {
    walk(val, [_, v])
    v.ir_type == "String"
    weak_algo_string(v.value)
}

value_has_weak_algo(val) {
    walk(val, [_, v])
    v.ir_type == "VariableReference"
    weak_algo_string(v.value)
}

value_has_weak_protocol(val) {
    walk(val, [_, v])
    v.ir_type == "String"
    weak_protocol_string(v.value)
